def validate(text):
    closers = {')': '(', ']': '[', '}': '{'}
    stack = []
    for i, ch in enumerate(text):
        if ch in '([{':
            stack.append(i)
        elif ch in closers:
            if not stack:
                return False
            top = stack[-1]
            if text[top] != closers[ch]:
                return False
            stack.pop()
    return not stack
